You don’t need a heavy stream-processing library for this. Node’s built-in fs and readline handle 500MB+ files safely with constant memory and backpressure.

Here’s a minimal, robust utility that streams a file line-by-line and yields only lines containing "ERROR".

// errorLines.js
const fs = require('fs');
const readline = require('readline');

async function* errorLines(filePath, options = {}) {
  const {
    pattern = 'ERROR',         // string or RegExp
    encoding = 'utf8',
    highWaterMark = 256 * 1024, // 256KB chunks
    signal,                    // optional AbortSignal
    includeLineNumber = true,
  } = options;

  const stream = fs.createReadStream(filePath, { encoding, highWaterMark });
  const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });

  // Normalize pattern matcher
  let matchFn;
  if (typeof pattern === 'string') {
    matchFn = (line) => line.includes(pattern);
  } else if (pattern instanceof RegExp) {
    // Avoid stateful /g by stripping it
    const flags = pattern.flags.replace(/g/g, '');
    const re = new RegExp(pattern.source, flags);
    matchFn = (line) => re.test(line);
  } else {
    rl.close();
    stream.destroy();
    throw new TypeError('pattern must be a string or RegExp');
  }

  // Optional abort support
  let onAbort;
  if (signal) {
    if (signal.aborted) {
      rl.close();
      stream.destroy();
      throw new Error('Aborted');
    }
    onAbort = () => {
      rl.close();
      stream.destroy(new Error('Aborted'));
    };
    signal.addEventListener('abort', onAbort, { once: true });
  }

  let lineNumber = 0;
  try {
    for await (const line of rl) {
      lineNumber++;
      if (matchFn(line)) {
        if (includeLineNumber) {
          yield { line, lineNumber };
        } else {
          yield line;
        }
      }
    }
  } finally {
    rl.close();
    stream.destroy();
    if (onAbort) signal.removeEventListener('abort', onAbort);
  }
}

module.exports = { errorLines };

Example usage:

// example.js
const { errorLines } = require('./errorLines');

(async () => {
  for await (const { line, lineNumber } of errorLines('app.log')) {
    console.log(`${lineNumber}: ${line}`);
  }
})().catch(err => {
  console.error('Failed:', err);
});

Notes:
- Uses constant memory and backpressure; safe for very large files.
- No external dependencies.
- You can pass a custom pattern (e.g., /ERROR\b/i) or set includeLineNumber: false to yield just the line strings.

def fetch_urls(urls, timeout=10.0):
    """
    Download each URL with a 10-second timeout and retry once on failure.
    Returns a dict mapping URL -> response text or an error string.
    Uses only the Python standard library.
    """
    import urllib.request
    import urllib.error
    import gzip
    import zlib
    import socket

    def _decompress_if_needed(data, headers):
        enc = headers.get("Content-Encoding", "")
        if not enc:
            return data
        enc = enc.lower()
        # Handle common encodings
        if "gzip" in enc or "x-gzip" in enc:
            try:
                return gzip.decompress(data)
            except Exception:
                # Fall through to raw zlib as a last resort
                try:
                    return zlib.decompress(data, 16 + zlib.MAX_WBITS)
                except Exception:
                    return data
        if "deflate" in enc:
            # Try zlib-wrapped first, then raw deflate
            try:
                return zlib.decompress(data)
            except Exception:
                try:
                    return zlib.decompress(data, -zlib.MAX_WBITS)
                except Exception:
                    return data
        # Unknown encoding: return raw
        return data

    def _decode_text(data, headers):
        # Try charset from Content-Type header
        # headers is http.client.HTTPMessage (email.message.Message)
        charset = None
        try:
            charset = headers.get_content_charset()
        except Exception:
            pass
        if not charset:
            # Fallback default; UTF-8 is the web default
            charset = "utf-8"
        try:
            return data.decode(charset, errors="replace")
        except LookupError:
            # Unknown codec; fallback to utf-8
            return data.decode("utf-8", errors="replace")

    def _fetch_once(url):
        req = urllib.request.Request(
            url,
            headers={
                # Ask for compressed content; we'll handle it
                "Accept-Encoding": "gzip, deflate",
                # Set a UA to avoid some servers rejecting default urllib UA
                "User-Agent": "python-urllib/3"
            },
            method="GET",
        )
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read()
            raw = _decompress_if_needed(raw, resp.headers)
            return _decode_text(raw, resp.headers)

    results = {}
    for url in urls:
        last_err = None
        for attempt in range(2):  # initial try + 1 retry
            try:
                results[url] = _fetch_once(url)
                break
            except urllib.error.HTTPError as e:
                # HTTPError is also a response; try to read body text for details
                try:
                    body = e.read()
                    body = _decompress_if_needed(body, e.headers)
                    text = _decode_text(body, e.headers)
                    last_err = f"HTTPError {e.code} {e.reason}: {text.strip()[:500]}"
                except Exception:
                    last_err = f"HTTPError {e.code} {e.reason}"
            except urllib.error.URLError as e:
                # URLError wraps many lower-level issues, including DNS and timeouts
                reason = getattr(e, "reason", None)
                if isinstance(reason, socket.timeout):
                    last_err = "Timeout after {}s".format(timeout)
                else:
                    last_err = f"URLError: {reason if reason else str(e)}"
            except socket.timeout:
                last_err = "Timeout after {}s".format(timeout)
            except Exception as e:
                last_err = f"Error: {e}"
            # If first attempt failed, loop once more for retry
        else:
            # Both attempts failed
            results[url] = last_err if last_err else "Unknown error"
    return results

Simplest fix:
- Enable WAL and set a busy timeout on every connection.
- Keep writes in short transactions.

Bun example:
import { Database } from "bun:sqlite";

const db = new Database("app.db");

// Enable WAL so readers can proceed while a writer appends to the WAL file
db.query("PRAGMA journal_mode = WAL").get();

// Have SQLite wait briefly instead of failing immediately with SQLITE_BUSY
db.query("PRAGMA busy_timeout = 2000").get(); // 2s is usually plenty

// Optional, good default for WAL
db.query("PRAGMA synchronous = NORMAL").get();

Why this works:
- By default (rollback journal) a writer blocks readers and SQLite returns SQLITE_BUSY immediately because the default busy timeout is 0 ms.
- WAL mode changes locking so reads can run concurrently with a writer; the writer appends to a WAL file while readers keep a stable snapshot. This removes most read/write conflicts.
- busy_timeout tells SQLite to retry for a short period when it still can’t get a lock (e.g., during brief exclusive phases like DDL, checkpoint, or when two writers overlap), turning transient lock contention into a short wait instead of an error.
- Keeping write transactions short minimizes the time any lock is held.

Extra low-effort wins:
- Reuse a single Database instance per process if you can; unnecessary extra connections increase contention.
- Avoid DDL during the background sync.

Decision
Choose (a): a single Bun script.

Why
- Scope fit: The tool does exactly one thing. A framework, plugin system, and build pipeline create surface area you don’t use.
- Operational simplicity: No build step, no plugin lifecycle, no dependency churn. Easier to run locally and in CI.
- Failure modes: Fewer moving parts means fewer places to break. Easier to reason about timeouts, DNS failures, and exit codes.
- Reversibility: You can add structure later. Starting with a framework is harder to reverse.

When to revisit (b)
Adopt a framework only if you hit concrete triggers:
- Multiple commands or checks (e.g., protocols beyond HTTP, content assertions, auth flows) with clearly separate concerns.
- Third‑party extensions you don’t control, requiring a stable plugin API and versioning.
- Distribution constraints (single binary without Bun; complex packaging; signed releases across OSes).
- Team size and change rate increase, making modular boundaries and explicit contracts necessary.

Minimal design for (a)
CLI contract
- Inputs:
  - --url or --config path/to/config.json
  - Optional: --method HEAD|GET (default HEAD), --timeout ms (default 10000), --retries n (default 0), --expect 200, --json, --quiet
- Behavior: Fetch URL with timeout and redirects-followed. Success only if final HTTP status equals expect (default 200).
- Outputs:
  - Human: “OK …” or “FAIL …” with status and timing.
  - JSON: { ok, url, status, durationMs, attempts, error? }
- Exit codes:
  - 0: success (status matched)
  - 2: status mismatch
  - 3: network/DNS/TLS error
  - 4: timeout

Config schema (JSON)
- { "url": string, "method"?: "HEAD" | "GET", "timeoutMs"?: number, "retries"?: number, "expectStatus"?: number, "headers"?: { [k: string]: string } }

Reference implementation (Bun, single file)
Save as check-200.ts and run with: bun check-200.ts --url https://example.com
You can also make it executable with a Bun shebang.

#!/usr/bin/env bun
// check-200.ts

type Config = {
  url: string
  method?: "GET" | "HEAD"
  timeoutMs?: number
  retries?: number
  expectStatus?: number
  headers?: Record<string, string>
  json?: boolean
  quiet?: boolean
}

type Result = {
  ok: boolean
  url: string
  status?: number
  durationMs: number
  attempts: number
  error?: string
}

function parseArgs(argv: string[]) {
  const args: Record<string, string | boolean> = {}
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i]
    if (a.startsWith("--")) {
      const key = a.slice(2)
      const next = argv[i + 1]
      if (next && !next.startsWith("--")) {
        args[key] = next
        i++
      } else {
        args[key] = true
      }
    }
  }
  return args
}

async function withTimeout<T>(ms: number, op: (signal: AbortSignal) => Promise<T>): Promise<T> {
  const ctrl = new AbortController()
  const t = setTimeout(() => ctrl.abort(), ms)
  try {
    return await op(ctrl.signal)
  } finally {
    clearTimeout(t)
  }
}

async function sleep(ms: number) {
  return new Promise((r) => setTimeout(r, ms))
}

async function checkUrl(urlStr: string, cfg: Required<Pick<Config, "method" | "timeoutMs" | "retries" | "expectStatus">> & Pick<Config, "headers">): Promise<Result> {
  let attempts = 0
  const start = Date.now()
  let lastErr: string | undefined
  while (attempts <= cfg.retries) {
    attempts++
    try {
      // Validate URL early
      const url = new URL(urlStr)
      const res = await withTimeout(cfg.timeoutMs, (signal) =>
        fetch(url, {
          method: cfg.method,
          headers: cfg.headers,
          redirect: "follow",
          signal,
        })
      )
      const durationMs = Date.now() - start
      const ok = res.status === cfg.expectStatus
      if (ok) {
        return { ok, url: urlStr, status: res.status, durationMs, attempts }
      } else {
        return { ok, url: urlStr, status: res.status, durationMs, attempts, error: `expected ${cfg.expectStatus}` }
      }
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e)
      lastErr = msg
      // If aborted due to timeout, stop retrying; caller maps to exit code 4.
      if (msg.includes("AbortError") || msg.toLowerCase().includes("aborted")) break
      // brief backoff before retry, unless this was the last attempt
      if (attempts <= cfg.retries) await sleep(Math.min(500, 100 + attempts * 150))
    }
  }
  const durationMs = Date.now() - start
  return { ok: false, url: urlStr, durationMs, attempts, error: lastErr ?? "unknown error" }
}

function loadConfig(path: string): Partial<Config> {
  const txt = Bun.file(path).textSync()
  try {
    return JSON.parse(txt)
  } catch {
    throw new Error(`Invalid JSON in config: ${path}`)
  }
}

async function main() {
  const args = parseArgs(Bun.argv)
  const wantJson = Boolean(args.json)
  const quiet = Boolean(args.quiet)

  let cfg: Partial<Config> = {}
  if (typeof args.config === "string") {
    cfg = { ...cfg, ...loadConfig(args.config) }
  }

  const url =
    (typeof args.url === "string" ? args.url : undefined) ??
    cfg.url

  if (!url) {
    console.error("Usage: bun check-200.ts --url https://example.com [--method HEAD|GET] [--timeout 10000] [--retries 0] [--expect 200] [--json] [--quiet] [--config path]")
    process.exit(1)
  }

  const method = (typeof args.method === "string" ? args.method.toUpperCase() : cfg.method) === "GET" ? "GET" : "HEAD"
  const timeoutMs = Number(args.timeout || cfg.timeoutMs || 10000)
  const retries = Number(args.retries ?? cfg.retries ?? 0)
  const expectStatus = Number(args.expect ?? cfg.expectStatus ?? 200)

  const headers: Record<string, string> | undefined = cfg.headers

  const result = await checkUrl(url, { method, timeoutMs, retries, expectStatus, headers })

  if (wantJson) {
    console.log(JSON.stringify(result))
  } else if (!quiet) {
    if (result.ok) {
      console.log(`OK ${result.url} status=${result.status} attempts=${result.attempts} durationMs=${result.durationMs}`)
    } else if (result.error?.toLowerCase().includes("abort")) {
      console.error(`TIMEOUT ${result.url} after ${result.durationMs}ms attempts=${result.attempts}`)
    } else if (typeof result.status === "number") {
      console.error(`FAIL ${result.url} status=${result.status} expected=${expectStatus} attempts=${result.attempts} durationMs=${result.durationMs}`)
    } else {
      console.error(`ERROR ${result.url} error="${result.error}" attempts=${result.attempts} durationMs=${result.durationMs}`)
    }
  }

  if (result.ok) process.exit(0)
  if (result.error?.toLowerCase().includes("abort")) process.exit(4)
  if (typeof result.status === "number") process.exit(2)
  process.exit(3)
}

main().catch((e) => {
  console.error(`ERROR ${e instanceof Error ? e.message : String(e)}`)
  process.exit(3)
})

Notes
- HEAD by default avoids downloading bodies; switch to GET if your origin doesn’t support HEAD.
- Keep JSON config to avoid a YAML parser dependency.
- This structure leaves a seam: checkUrl is a pure function the CLI wraps. If growth demands (b), you can lift this into a library and add a thin plugin/command layer without rewriting the core.

