### 5.3 JSON formatter (existing, wrapped)

```ts
export class JsonCustomerFormatter implements ExportFormatter<Customer> {
  async format(records: AsyncIterable<Customer> | Iterable<Customer>): Promise<ExportArtifact> {
    const arr: Customer[] = [];
    for await (const r of records as any) arr.push(r);

    const json = JSON.stringify(arr);
    return {
      filename: `customers-${new Date().toISOString()}.json`,
      contentType: "application/json",
      bytes: Buffer.from(json, "utf-8"),
    };
  }
}
```

### 5.4 CSV formatter (new)

```ts
const CUSTOMER_COLUMNS: Array<{ header: string; get: (c: Customer) => unknown }> = [
  { header: "id",        get: c => c.id },
  { header: "email",     get: c => c.email ?? "" },
  { header: "fullName",  get: c => c.fullName },
  { header: "createdAt", get: c => c.createdAt },
  { header: "status",    get: c => c.status },
];

function csvEscape(value: unknown): string {
  if (value === null || value === undefined) return "";
  const s = String(value);

  // Quote if it contains delimiter, quote, or newline.
  if (/[",\n\r]/.test(s)) {
    return `"${s.replace(/"/g, `""`)}"`;
  }
  return s;
}

export class CsvCustomerFormatter implements ExportFormatter<Customer> {
  async format(records: AsyncIterable<Customer> | Iterable<Customer>): Promise<ExportArtifact> {
    const lines: string[] = [];
    lines.push(CUSTOMER_COLUMNS.map(c => c.header).join(","));

    for await (const r of records as any) {
      const row = CUSTOMER_COLUMNS.map(col => csvEscape(col.get(r))).join(",");
      lines.push(row);
    }

    const csv = lines.join("\n") + "\n";
    return {
      filename: `customers-${new Date().toISOString()}.csv`,
      contentType: "text/csv; charset=utf-8",
      bytes: Buffer.from(csv, "utf-8"),
    };
  }
}
```

### 5.5 Export service selects formatter

```ts
export type ExportFormat = "json" | "csv";

export class CustomerExportService {
  constructor(
    private readonly customerRepo: { streamAll(): AsyncIterable<Customer> },
    private readonly jsonFormatter: JsonCustomerFormatter,
    private readonly csvFormatter: CsvCustomerFormatter,
  ) {}

  async exportAll(format: ExportFormat): Promise<ExportArtifact> {
    const records = this.customerRepo.streamAll();
    switch (format) {
      case "json": return this.jsonFormatter.format(records);
      case "csv":  return this.csvFormatter.format(records);
      default: throw new Error(`Unsupported format: ${format}`);
    }
  }
}
```

