  "name": "bun-sqlite-wal-fix",
  "module": "index.ts",
  "type": "module",
  "devDependencies": {
    "bun-types": "latest"
  }
}
```

**`tsconfig.json`**
```json
{
  "compilerOptions": {
    "lib": ["ESNext"],
    "module": "ESNext",
    "target": "ESNext",
    "moduleResolution": "bundler",
    "strict": true,
    "esModuleInterop": true,
    "types": ["bun-types"]
  }
}
```

**`index.ts`**
```typescript
import { Database } from "bun:sqlite";
import { unlinkSync, existsSync } from "fs";

const DB_FILE = "test.sqlite";

// Clean up previous run
if (existsSync(DB_FILE)) unlinkSync(DB_FILE);
if (existsSync(`${DB_FILE}-wal`)) unlinkSync(`${DB_FILE}-wal`);
if (existsSync(`${DB_FILE}-shm`)) unlinkSync(`${DB_FILE}-shm`);

// 1. Open the database.
const db = new Database(DB_FILE, { create: true });

// 2. Verify the default mode.
let { journal_mode: defaultMode } = db.query("PRAGMA journal_mode;").get() as { journal_mode: string };
console.log(`[VERIFY] Default journal mode: ${defaultMode}`); // Expected: 'delete'

// 3. Apply the fix: Enable WAL mode.
db.exec("PRAGMA journal_mode = WAL;");
console.log("[ACTION] Set journal_mode = WAL");

// 4. Verify the new mode.
let { journal_mode: newMode } = db.query("PRAGMA journal_mode;").get() as { journal_mode: string };
console.log(`[VERIFY] New journal mode: ${newMode}`); // Expected: 'wal'

// 5. Demonstrate non-blocking behavior (simulation).
db.exec("CREATE TABLE IF NOT EXISTS data (id INTEGER PRIMARY KEY, value TEXT);");

// Simulate a long-running background write transaction.
// In WAL mode, this will NOT block the reader below.
console.log("\n[DEMO] Starting simulated background write...");
const writer = new Database(DB_FILE);
writer.exec("BEGIN IMMEDIATE;"); // Start a write transaction
writer.exec("INSERT INTO data (value) VALUES ('background data');");

// Simulate a foreground read happening *during* the write.
console.log("[DEMO] Attempting foreground read during write...");
try {
    const data = db.query("SELECT * FROM data;").all();
    console.log("[SUCCESS] Read completed without SQLITE_BUSY.");
    console.log("[RESULT] Data read:", data);
} catch (e) {
    console.error("[FAILURE] Read failed:", e);
}

// Finish the write.
writer.exec("COMMIT;");
console.log("[DEMO] Background write committed.");

writer.close();
db.close();
```

Run this with `bun run index.ts`. The output will confirm the mode change and the success of the read operation during the simulated write. This is the simplest, most correct solution for enabling reader/writer concurrency in SQLite.

