const readline = require('readline');

/**
 * Reads a local log file line-by-line and processes lines containing 'ERROR'.
 * Memory consumption remains constant regardless of file size.
 * 
 * @param {string} filePath - Path to the local log file.
 * @param {function(string): void} onMatch - Callback invoked for each matching line.
 * @returns {Promise<number>} - Resolves with the total count of matched lines.
 */
function parseErrors(filePath, onMatch) {
  return new Promise((resolve, reject) => {
    if (!filePath) {
      return reject(new Error('File path is required.'));
    }

    let matchCount = 0;

    // Create a read stream with native system primitives
    const fileStream = fs.createReadStream(filePath, { encoding: 'utf8' });

    // Use the native readline interface to handle line-by-line buffering
    const rl = readline.createInterface({
      input: fileStream,
      crlfDelay: Infinity // Recognizes both \r\n and \n correctly
    });

    rl.on('line', (line) => {
      if (line.includes('ERROR')) {
        matchCount++;
        onMatch(line);
      }
    });

    rl.on('close', () => {
      resolve(matchCount);
    });

    // Handle stream errors (e.g., file not found, permission issues)
    fileStream.on('error', (err) => {
      reject(err);
    });
  });
}

module.exports = { parseErrors };
```

