### 3. The Implementation (`monitor.py`)

Save the following code as `monitor.py`. It is completely self-contained and requires no `pip install` commands.

```python
#!/usr/bin/env python3
import os
import sys
import time
import math
import sqlite3
import json
import shutil
import platform
import subprocess
import threading
import urllib.request
from http.server import BaseHTTPRequestHandler, HTTPServer

# --- CONFIGURATION ---
DB_FILE = "metrics.db"
ALERT_LOG_FILE = "alerts.log"
PORT = 8080
COLLECTION_INTERVAL = 10  # seconds
ROLLING_WINDOW_SIZE = 60  # number of data points for anomaly detection baseline
Z_SCORE_THRESHOLD = 3.0   # standard deviations to trigger anomaly alert

# HTTP Targets to monitor (Synthetic Monitoring)
HTTP_TARGETS = {
    "Google_DNS": "https://8.8.8.8",
    "GitHub": "https://github.com"
}

# --- DATABASE INITIALIZATION ---
def init_db():
    conn = sqlite3.connect(DB_FILE)
    cursor = conn.cursor()
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS metrics (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
            metric_name TEXT,
            metric_value REAL
        )
    """)
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS alerts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
            metric_name TEXT,
            metric_value REAL,
            message TEXT,
            severity TEXT
        )
    """)
    conn.commit()
    conn.close()

def write_metric(name, value):
    conn = sqlite3.connect(DB_FILE)
    cursor = conn.cursor()
    cursor.execute("INSERT INTO metrics (metric_name, metric_value) VALUES (?, ?)", (name, value))
    conn.commit()
    conn.close()

def write_alert(name, value, message, severity):
    conn = sqlite3.connect(DB_FILE)
    cursor = conn.cursor()
    cursor.execute(
        "INSERT INTO alerts (metric_name, metric_value, message, severity) VALUES (?, ?, ?, ?)",
        (name, value, message, severity)
    )
    conn.commit()
    conn.close()

# --- METRIC COLLECTORS ---
def get_disk_usage():
    try:
        total, used, free = shutil.disk_usage("/")
        return (used / total) * 100.0
    except Exception:
        return 0.0

def get_cpu_usage():
    system = platform.system()
    try:
        if system == "Linux":
            with open('/proc/stat', 'r') as f:
                fields1 = [float(x) for x in f.readline().strip().split()[1:]]
            time.sleep(0.2)
            with open('/proc/stat', 'r') as f:
                fields2 = [float(x) for x in f.readline().strip().split()[1:]]
            idle1, total1 = fields1[3], sum(fields1)
            idle2, total2 = fields2[3], sum(fields2)
            idle_delta = idle2 - idle1
            total_delta = total2 - total1
            if total_delta == 0:
                return 0.0
            return (1.0 - idle_delta / total_delta) * 100.0
        elif system == "Darwin":
            # macOS fallback using sysctl load average
            out = subprocess.check_output(["sysctl", "-n", "vm.loadavg"]).decode().strip()
            load = float(out.split()[1]) # 1-minute load average
            return min(load * 10.0, 100.0)
        elif system == "Windows":
            out = subprocess.check_output("wmic cpu get LoadPercentage", shell=True).decode()
            lines = [line.strip() for line in out.split('\n') if line.strip()]
            if len(lines) > 1:
                return float(lines[1])
    except Exception:
        pass
    return 0.0

def get_http_latency(url):
    start = time.time()
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'LocalMonitor/1.0'})
        with urllib.request.urlopen(req, timeout=5) as response:
            response.read()
        return (time.time() - start) * 1000.0  # ms
    except Exception:
        return -1.0  # -1 indicates offline/error

# --- ANOMALY DETECTION & ALERTING ---
def get_historical_values(metric_name, limit):
    conn = sqlite3.connect(DB_FILE)
    cursor = conn.cursor()
    cursor.execute(
        "SELECT metric_value FROM metrics WHERE metric_name = ? ORDER BY timestamp DESC LIMIT ?",
        (metric_name, limit)
    )
    rows = cursor.fetchall()
    conn.close()
    return [row[0] for row in rows]

def dispatch_alert(metric_name, value, message, severity="WARNING"):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    alert_text = f"[{timestamp}] [{severity}] {metric_name}: {message} (Current Value: {value:.2f})"

    # 1. Write to stdout
    print(alert_text, flush=True)

    # 2. Write to local log file
    with open(ALERT_LOG_FILE, "a") as f:
        f.write(alert_text + "\n")

    # 3. Write to SQLite
    write_alert(metric_name, value, message, severity)

    # 4. Optional Webhook Dispatch (Discord/Slack compatible)
    webhook_url = os.environ.get("MONITOR_WEBHOOK_URL")
    if webhook_url:
        try:
            payload = json.dumps({"content": alert_text}).encode('utf-8')
            req = urllib.request.Request(
                webhook_url,
                data=payload,
                headers={'Content-Type': 'application/json', 'User-Agent': 'LocalMonitor/1.0'}
            )
            with urllib.request.urlopen(req, timeout=5) as response:
                response.read()
        except Exception as e:
            print(f"Failed to dispatch webhook alert: {e}", flush=True)

def analyze_and_detect(metric_name, current_value):
    # Fetch historical baseline
    history = get_historical_values(metric_name, ROLLING_WINDOW_SIZE)
    if len(history) < ROLLING_WINDOW_SIZE:
        return  # Wait for baseline to populate

    # Calculate Mean and Standard Deviation
    mean = sum(history) / len(history)
    variance = sum((x - mean) ** 2 for x in history) / len(history)
    std_dev = math.sqrt(variance)

    if std_dev < 0.01:
        return  # Avoid division by zero or alerting on static metrics

    z_score = (current_value - mean) / std_dev

    # Trigger alert if Z-Score exceeds threshold
    if abs(z_score) > Z_SCORE_THRESHOLD:
        msg = f"Anomaly detected! Metric deviated by {z_score:.2f} standard deviations from rolling mean ({mean:.2f})."
        dispatch_alert(metric_name, current_value, msg, "CRITICAL")

# --- BACKGROUND MONITORING LOOP ---
def monitoring_loop():
    init_db()
    print("[*] Monitoring engine started successfully.", flush=True)
    while True:
        try:
            # 1. Collect System Metrics
            cpu = get_cpu_usage()
            disk = get_disk_usage()

            write_metric("system_cpu_usage", cpu)
            write_metric("system_disk_usage", disk)

            analyze_and_detect("system_cpu_usage", cpu)
            analyze_and_detect("system_disk_usage", disk)

            # Static Threshold Alerts
            if disk > 90.0:
                dispatch_alert("system_disk_usage", disk, "Disk usage exceeds critical threshold of 90%", "CRITICAL")

            # 2. Collect Synthetic HTTP Metrics
            for name, url in HTTP_TARGETS.items():
                latency = get_http_latency(url)
                metric_key = f"http_latency_{name}"
                write_metric(metric_key, latency)

                if latency == -1.0:
                    dispatch_alert(metric_key, latency, f"Target {url} is unreachable or timed out.", "CRITICAL")
                else:
                    analyze_and_detect(metric_key, latency)

        except Exception as e:
            print(f"[!] Error in monitoring loop: {e}", flush=True)

        time.sleep(COLLECTION_INTERVAL)

# --- EMBEDDED DASHBOARD SERVER ---
