class MonitorDashboardHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        return  # Suppress standard HTTP logging to keep stdout clean for alerts

    def do_GET(self):
        if self.path == "/":
            self.send_response(200)
            self.send_header("Content-Type", "text/html")
            self.end_headers()
            self.wfile.write(HTML_DASHBOARD.encode('utf-8'))
        elif self.path == "/api/metrics":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()

            conn = sqlite3.connect(DB_FILE)
            cursor = conn.cursor()
            # Fetch last 100 metrics
            cursor.execute("""
                SELECT timestamp, metric_name, metric_value 
                FROM metrics 
                ORDER BY id DESC LIMIT 200
            """)
            rows = cursor.fetchall()
            conn.close()

            data = [{"timestamp": r[0], "metric_name": r[1], "metric_value": r[2]} for r in rows]
            self.wfile.write(json.dumps(data).encode('utf-8'))

        elif self.path == "/api/alerts":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()

            conn = sqlite3.connect(DB_FILE)
            cursor = conn.cursor()
            cursor.execute("""
                SELECT timestamp, metric_name, metric_value, message, severity 
                FROM alerts 
                ORDER BY id DESC LIMIT 20
            """)
            rows = cursor.fetchall()
            conn.close()

            data = [
                {
                    "timestamp": r[0],
                    "metric_name": r[1],
                    "metric_value": r[2],
                    "message": r[3],
                    "severity": r[4]
                } for r in rows
            ]
            self.wfile.write(json.dumps(data).encode('utf-8'))
        else:
            self.send_response(404)
            self.end_headers()

def run_dashboard_server():
    server = HTTPServer(('0.0.0.0', PORT), MonitorDashboardHandler)
    print(f"[*] Dashboard available at http://localhost:{PORT}", flush=True)
    server.serve_forever()

# --- ENTRY POINT ---
