The assertion that a heavy stream-processing library from npm is required to safely process a 500MB file is empirically false. Node.js provides native, built-in primitives that handle memory management, chunking, and backpressure efficiently without external bloat. Introducing third-party dependencies for this task violates minimalist architecture principles.

We will use the native `fs` and `readline` modules. `fs.createReadStream` reads the file in manageable chunks, and `readline` parses those chunks into lines, ensuring constant memory usage regardless of the 500MB file size.

Here is the zero-dependency utility function using an async generator for optimal memory efficiency:

```javascript
const fs = require('fs');
const readline = require('readline');
const path = require('path');

/**
 * Streams a large text file line-by-line and yields lines containing 'ERROR'.
 * 
 * @param {string} filePath - The path to the local log file.
 * @yields {string} - Lines containing the 'ERROR' substring.
 */
async function* streamErrorLines(filePath) {
  const absolutePath = path.resolve(filePath);

  // Native stream handles chunking and backpressure natively.
  const fileStream = fs.createReadStream(absolutePath, { encoding: 'utf8' });

  // Native readline interface parses the stream into lines.
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity // Recognizes all line endings (CR, LF, CRLF)
  });

  for await (const line of rl) {
    if (line.includes('ERROR')) {
