import { file } from "bun";

interface Config {
  url: string;
}

async function main() {
  // 1. Resolve config path from arguments, default to config.json
  const configPath = process.argv[2] || "config.json";
  const configFile = file(configPath);

  if (!(await configFile.exists())) {
    console.error(`Error: Config file not found at ${configPath}`);
    process.exit(1);
  }

  // 2. Parse configuration
  let config: Config;
  try {
    config = await configFile.json();
  } catch (err) {
    console.error(`Error: Failed to parse JSON in ${configPath}`);
    process.exit(1);
  }

  if (!config.url || typeof config.url !== "string") {
    console.error("Error: Config must contain a valid 'url' string.");
    process.exit(1);
  }

  // 3. Execute fetch and evaluate
  try {
    const response = await fetch(config.url);

    if (response.status === 200) {
      console.log(`Success: ${config.url} returned 200`);
      process.exit(0);
    } else {
      console.error(`Failure: ${config.url} returned ${response.status}`);
      process.exit(1);
    }
  } catch (error) {
    console.error(`Failure: Network error or invalid URL for ${config.url}`);
    process.exit(1);
  }
}

main();
```

