// 2️⃣ Apply pragmas once, right after opening
db.exec(`
  -- Enable WAL – allows concurrent reads/writes
  PRAGMA journal_mode = WAL;

  -- Wait up to 5 000 ms for a lock before returning SQLITE_BUSY
  PRAGMA busy_timeout = 5000;
`);

// Helper: run a function inside a transaction with automatic retry
export async function runInTransaction<T>(
  fn: () => Promise<T>,
  retries = 3,
  retryDelayMs = 200
): Promise<T> {
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      db.exec("BEGIN IMMEDIATE;"); // acquire a write lock early
      const result = await fn();
      db.exec("COMMIT;");
      return result;
    } catch (err: any) {
      db.exec("ROLLBACK;"); // always clean up

      // SQLITE_BUSY (code 5) is the only error we want to retry
      if (err?.code === "SQLITE_BUSY" && attempt < retries) {
        await new Promise((r) => setTimeout(r, retryDelayMs));
        continue; // retry
      }
      throw err; // re‑throw any other error or exhausted retries
    }
  }
  // Should never reach here
  throw new Error("Transaction retry exhausted");
}
```

