Below is a self-contained utility. It streams the file, emits lines lazily, and filters for `ERROR`. It uses only Node's standard library.

```js
// filterErrors.js
'use strict';

const fs = require('fs');
const readline = require('readline');

/**
 * Reads a local text log file line-by-line and yields lines containing 'ERROR'.
 *
 * @param {string} filePath - Absolute or relative path to the log file.
 * @param {object} [options]
 * @param {number} [options.highWaterMark=65536] - Read buffer size in bytes.
 * @returns {AsyncGenerator<string, void, void>} Lines containing 'ERROR'.
 */
async function* filterErrorLines(filePath, options = {}) {
  const { highWaterMark = 64 * 1024 } = options;

  const stream = fs.createReadStream(filePath, {
    encoding: 'utf8',
    highWaterMark,
  });

  const rl = readline.createInterface({
    input: stream,
    crlfDelay: Infinity, // tolerate \r\n, \r, or \n
  });

  try {
    for await (const line of rl) {
      if (line.includes('ERROR')) {
        yield line;
      }
    }
  } finally {
    rl.close();
    stream.destroy();
  }
}

module.exports = { filterErrorLines };

// CLI entrypoint: node filterErrors.js ./app.log
if (require.main === module) {
  const file = process.argv[2];
  if (!file) {
    console.error('Usage: node filterErrors.js <logFile>');
    process.exit(2);
  }

  (async () => {
    try {
      let count = 0;
      for await (const line of filterErrorLines(file)) {
        console.log(line);
        count++;
      }
      process.stderr.write(`\n${count} ERROR line(s) emitted.\n`);
    } catch (err) {
      console.error('Failed:', err);
      process.exit(1);
    }
  })();
}
```

Usage:

```sh
node filterErrors.js ./app.log > errors.txt
```

Notes:

- `readline.createInterface` with `for await...of` is backpressure-aware; it does not load the whole 500MB into memory.
- `crlfDelay: Infinity` handles mixed line endings without a custom parser.
- `includes('ERROR')` is a plain substring check. If you need case-insensitive or regex matching, swap in `line.match(/error/i)` — still no external dependency warranted.
- The `finally` block ensures the underlying stream is destroyed even if the consumer breaks early.

If you later need to handle multi-line stack traces (where the `ERROR` line is followed by continuation lines), that is a different problem and worth stating explicitly before reaching for anything heavier. For the requirement as given, native primitives are sufficient and preferable.

