	defer tb.mu.Unlock()

	now := time.Now()
	elapsed := now.Sub(tb.lastRefill).Minutes()
	refilled := int(elapsed * float64(tb.refillRate))

	if refilled > 0 {
		tb.tokens = int(math.Min(float64(tb.capacity), float64(tb.tokens+refilled)))
		tb.lastRefill = now
	}

	if tb.tokens > 0 {
		tb.tokens--
		return true
	}
	return false
}

func newRateLimiter() *RateLimiter {
	return &RateLimiter{
		channels: make(map[string]*tokenBucket),
	}
}

func (rl *RateLimiter) setChannel(channel string, capacity, refillRate int) {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.channels[channel] = newTokenBucket(capacity, refillRate)
}

func (rl *RateLimiter) allow(channel string) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	bucket, exists := rl.channels[channel]
	if !exists {
		return true // No rate limiting if not configured
	}
	return bucket.allow()
}

// TemplateEngine handles message templating
type TemplateEngine struct {
	templates map[string]*template.Template
	mu        sync.RWMutex
}

func newTemplateEngine() *TemplateEngine {
	return &TemplateEngine{
		templates: make(map[string]*template.Template),
	}
}

func (te *TemplateEngine) parse(name, tmpl string) error {
	t, err := template.New(name).Parse(tmpl)
	if err != nil {
		return err
	}
	te.mu.Lock()
	defer te.mu.Unlock()
	te.templates[name] = t
	return nil
}

func (te *TemplateEngine) execute(name string, data interface{}) (string, error) {
	te.mu.RLock()
	t, exists := te.templates[name]
	te.mu.RUnlock()

	if !exists {
		return "", fmt.Errorf("template %s not found", name)
	}

	var buf bytes.Buffer
	err := t.Execute(&buf, data)
	if err != nil {
		return "", err
	}
	return buf.String(), nil
}

