// NotificationService orchestrates sending notifications
type NotificationService struct {
	channels     map[string]Channel
	rateLimiter  *RateLimiter
	templateEngine *TemplateEngine
	configs      map[string]ChannelConfig
	mu           sync.RWMutex
}

func newNotificationService() *NotificationService {
	return &NotificationService{
		channels:     make(map[string]Channel),
		rateLimiter:  newRateLimiter(),
		templateEngine: newTemplateEngine(),
		configs:      make(map[string]ChannelConfig),
	}
}

func (ns *NotificationService) addChannel(channel Channel, config ChannelConfig) {
	ns.mu.Lock()
	defer ns.mu.Unlock()

	ns.channels[channel.Name()] = channel
	ns.configs[channel.Name()] = config

	// Set up rate limiting
	if config.RateLimit > 0 {
		ns.rateLimiter.setChannel(channel.Name(), config.RateLimit, config.RateLimit)
	}
}

func (ns *NotificationService) registerTemplate(name, tmpl string) error {
	return ns.templateEngine.parse(name, tmpl)
}

func (ns *NotificationService) sendWithRetry(notification Notification) error {
	ns.mu.RLock()
	channel, exists := ns.channels[notification.Channel]
	config := ns.configs[notification.Channel]
	ns.mu.RUnlock()

	if !exists {
		return fmt.Errorf("channel %s not found", notification.Channel)
	}

	if !config.Enabled {
		return fmt.Errorf("channel %s is disabled", notification.Channel)
	}

	// Check rate limiting
	if !ns.rateLimiter.allow(notification.Channel) {
		return fmt.Errorf("rate limit exceeded for channel %s", notification.Channel)
	}

	// Apply template if data is provided
	if len(notification.TemplateData) > 0 {
		rendered, err := ns.templateEngine.execute(notification.Channel, notification.TemplateData)
		if err != nil {
			return fmt.Errorf("template error: %w", err)
		}
		notification.Body = rendered
	}

	// Retry logic
	var lastErr error
	for attempt := 0; attempt <= config.RetryCount; attempt++ {
		if attempt > 0 {
			log.Printf("Retrying %s notification (attempt %d/%d)", 
				notification.Channel, attempt, config.RetryCount)
			time.Sleep(config.RetryDelay * time.Duration(attempt))
		}

		err := channel.Send(notification)
		if err == nil {
			log.Printf("Successfully sent %s notification to %s", 
				notification.Channel, notification.To)
			return nil
		}

		lastErr = err
		log.Printf("Failed to send %s notification: %v", notification.Channel, err)
	}

	return fmt.Errorf("failed after %d retries: %w", config.RetryCount, lastErr)
}

func (ns *NotificationService) Send(notification Notification) error {
	return ns.sendWithRetry(notification)
}

// HTTP handler for receiving notifications
func (ns *NotificationService) handleNotification(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var notification Notification
	body, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Failed to read request body", http.StatusBadRequest)
		return
	}

	err = json.Unmarshal(body, &notification)
	if err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	notification.ID = fmt.Sprintf("%d", time.Now().UnixNano())

	err = ns.Send(notification)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status": "success", "id": "` + notification.ID + `"}`))
}

// Health check endpoint
func (ns *NotificationService) handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status": "healthy"}`))
}

