            available = meminfo.get('MemAvailable', meminfo.get('MemFree', 0))
            metrics['memory_total'] = total
            metrics['memory_available'] = available
            metrics['memory_used'] = total - available
            metrics['memory_available_percent'] = (available / total) * 100
            metrics['memory_used_percent'] = ((total - available) / total) * 100
    except:
