def detect_anomalies(config):
    """Detect anomalies using statistical methods"""
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    anomalies = []
    threshold = config.get('anomaly_threshold', 2.0)

    # Get recent metrics for each metric type
    c.execute('SELECT DISTINCT metric_name FROM metrics')
    metric_names = [row[0] for row in c.fetchall()]

    for metric_name in metric_names:
        # Get last 100 data points
        c.execute(
            'SELECT value FROM metrics WHERE metric_name = ? ORDER BY timestamp DESC LIMIT 100',
            (metric_name,)
        )
        values = [row[0] for row in c.fetchall()]

        if len(values) < 10:
            continue

        mean_val = statistics.mean(values)
        stdev_val = statistics.stdev(values) if len(values) > 1 else 0

        if stdev_val == 0:
            continue

        # Check latest value
        latest_value = values[0]
        z_score = abs(latest_value - mean_val) / stdev_val

        if z_score > threshold:
            anomalies.append({
                'metric': metric_name,
                'value': latest_value,
                'mean': mean_val,
                'z_score': z_score,
                'timestamp': int(time.time())
            })

    conn.close()
    return anomalies

def check_alerts(config):
