    for rule in config.get('alerts', []):
        metric_name = rule['metric']
        condition = rule['condition']
        threshold = rule['threshold']

        # Get latest value
        c.execute(
            'SELECT value FROM metrics WHERE metric_name = ? ORDER BY timestamp DESC LIMIT 1',
            (metric_name,)
        )
        row = c.fetchone()

        if row:
            value = row[0]
            triggered = False

            if condition == '>' and value > threshold:
                triggered = True
            elif condition == '<' and value < threshold:
                triggered = True
            elif condition == '>=' and value >= threshold:
                triggered = True
            elif condition == '<=' and value <= threshold:
                triggered = True
            elif condition == '==' and value == threshold:
                triggered = True

            if triggered:
                alert = {
                    'rule_name': rule['name'],
                    'metric_name': metric_name,
                    'value': value,
                    'threshold': threshold,
                    'severity': rule['severity'],
                    'timestamp': int(time.time())
                }
                triggered_alerts.append(alert)

                # Store alert in database
                c.execute('''
                    INSERT INTO alerts 
                    (timestamp, rule_name, metric_name, value, threshold, severity, status)
                    VALUES (?, ?, ?, ?, ?, ?, 'active')
                ''', (
