    cutoff_time = int(time.time()) - (retention_days * 24 * 60 * 60)

    c.execute('DELETE FROM metrics WHERE timestamp < ?', (cutoff_time,))
    c.execute('DELETE FROM alerts WHERE timestamp < ? AND status = "resolved"', (cutoff_time,))

    conn.commit()
    conn.close()

