    def handle_api(self):
        if self.path == '/api/metrics/latest':
            self.send_json_response(self.get_latest_metrics())
        elif self.path == '/api/metrics/history':
            self.send_json_response(self.get_metrics_history())
        elif self.path == '/api/alerts':
            self.send_json_response(self.get_alerts())
        else:
            self.send_error(404)

    def get_latest_metrics(self):
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        metrics = {}
        metric_names = ['cpu_percent', 'memory_used_percent', 'memory_available_percent', 
                       'disk_used_percent', 'network_rx_bytes', 'network_tx_bytes']

        for name in metric_names:
            c.execute(
                'SELECT value FROM metrics WHERE metric_name = ? ORDER BY timestamp DESC LIMIT 1',
                (name,)
            )
            row = c.fetchone()
            if row:
                metrics[name] = row[0]

        conn.close()
        return metrics

    def get_metrics_history(self):
        # Parse query parameters
        params = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
        hours = int(params.get('hours', [1])[0])

        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        cutoff = int(time.time()) - (hours * 3600)

        data = {
            'timestamps': [],
            'cpu': [],
            'memory': [],
            'disk': []
        }

        # Get timestamps
        c.execute(
            'SELECT DISTINCT timestamp FROM metrics WHERE timestamp > ? ORDER BY timestamp',
            (cutoff,)
        )
        timestamps = [row[0] for row in c.fetchall()]
        data['timestamps'] = [datetime.fromtimestamp(ts).strftime('%H:%M:%S') for ts in timestamps]

        # Get CPU values
        c.execute(
            'SELECT timestamp, value FROM metrics WHERE metric_name = "cpu_percent" AND timestamp > ? ORDER BY timestamp',
            (cutoff,)
        )
        cpu_data = {row[0]: row[1] for row in c.fetchall()}
        data['cpu'] = [cpu_data.get(ts, 0) for ts in timestamps]

        # Get Memory values
        c.execute(
            'SELECT timestamp, value FROM metrics WHERE metric_name = "memory_used_percent" AND timestamp > ? ORDER BY timestamp',
            (cutoff,)
        )
        mem_data = {row[0]: row[1] for row in c.fetchall()}
        data['memory'] = [mem_data.get(ts, 0) for ts in timestamps]

        # Get Disk values
        c.execute(
            'SELECT timestamp, value FROM metrics WHERE metric_name = "disk_used_percent" AND timestamp > ? ORDER BY timestamp',
            (cutoff,)
        )
        disk_data = {row[0]: row[1] for row in c.fetchall()}
        data['disk'] = [disk_data.get(ts, 0) for ts in timestamps]

        conn.close()
        return data

    def get_alerts(self):
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        c.execute('''
            SELECT timestamp, rule_name, metric_name, value, threshold, severity, status
            FROM alerts ORDER BY timestamp DESC LIMIT 50
        ''')

        alerts = []
        for row in c.fetchall():
            alerts.append({
                'timestamp': row[0],
                'rule_name': row[1],
                'metric_name': row[2],
                'value': row[3],
                'threshold': row[4],
                'severity': row[5],
                'status': row[6]
            })

        conn.close()
        return alerts

    def send_json_response(self, data):
        self.send_response(200)
        self.send_header('Content-type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

