                                                 │
                                    ┌────────────▼──────────┐
                                    │ Auto-Remediate?       │
                                    └────────┬──────┬───────┘
                                             │      │
                                        Yes  │      │  No
                                             ▼      ▼
                                        ┌────┐  ┌──────────┐
                                        │Exec│  │User Input│
                                        └─┬──┘  └────┬─────┘
                                          │          │
