# Customer Data Export Service: JSON → CSV Extension

I'll build a comprehensive end-to-end solution for extending your export service with CSV support.

## 1. Core CSV Formatter

```python
# src/exporters/formatters/csv_formatter.py
import csv
import io
from abc import ABC, abstractmethod
from dataclasses import asdict, fields, is_dataclass
from datetime import datetime
from decimal import Decimal
from enum import Enum
from typing import Any, Dict, List, Optional, Type, TypeVar, Union

T = TypeVar('T')


class FormatterError(Exception):
    """Base exception for formatter errors."""
    pass


class UnsupportedTypeError(FormatterError):
    """Raised when a field type cannot be serialized."""
    pass


class BaseFormatter(ABC):
    """Abstract base for data formatters."""

    @abstractmethod
    def format(self, data: List[Any]) -> str:
        """Format data and return as string."""
        pass

    @abstractmethod
    def get_content_type(self) -> str:
        """Return MIME type for this format."""
        pass

    @abstractmethod
    def get_file_extension(self) -> str:
        """Return file extension for this format."""
        pass


class CSVFormatter(BaseFormatter):
    """Formats customer data as CSV with robust type handling."""

    def __init__(
        self,
        delimiter: str = ',',
        quoting: int = csv.QUOTE_MINIMAL,
        include_headers: bool = True,
        date_format: str = '%Y-%m-%d',
        datetime_format: str = '%Y-%m-%d %H:%M:%S',
        decimal_places: Optional[int] = None,
        null_value: str = '',
    ):
        self.delimiter = delimiter
        self.quoting = quoting
        self.include_headers = include_headers
        self.date_format = date_format
        self.datetime_format = datetime_format
        self.decimal_places = decimal_places
        self.null_value = null_value

    def format(self, data: List[Any]) -> str:
        """
        Convert list of objects to CSV string.

        Args:
            data: List of dataclass instances or dicts

        Returns:
            CSV formatted string

        Raises:
            FormatterError: If data cannot be formatted
        """
        if not data:
            return ''

        try:
            # Normalize to list of dicts
            records = [self._to_dict(item) for item in data]

            # Extract all unique field names (preserving order)
            fieldnames = self._extract_fieldnames(records)

            # Serialize to CSV
            output = io.StringIO()
            writer = csv.DictWriter(
                output,
                fieldnames=fieldnames,
                delimiter=self.delimiter,
                quoting=self.quoting,
                extrasaction='ignore',
            )

            if self.include_headers:
                writer.writeheader()

            for record in records:
                serialized = self._serialize_record(record, fieldnames)
                writer.writerow(serialized)

            return output.getvalue()

        except Exception as e:
            raise FormatterError(f"Failed to format data as CSV: {e}") from e

    def get_content_type(self) -> str:
        return 'text/csv'

    def get_file_extension(self) -> str:
        return '.csv'

    def _to_dict(self, item: Any) -> Dict[str, Any]:
        """Convert item to dictionary."""
        if isinstance(item, dict):
            return item
        if is_dataclass(item):
            return asdict(item)
        raise FormatterError(
            f"Cannot convert {type(item).__name__} to dict. "
            "Expected dataclass or dict."
        )

    def _extract_fieldnames(self, records: List[Dict]) -> List[str]:
        """Extract and order field names from records."""
        seen = {}
        for record in records:
            for key in record.keys():
                if key not in seen:
                    seen[key] = True
        return list(seen.keys())

    def _serialize_record(
        self,
        record: Dict[str, Any],
        fieldnames: List[str],
    ) -> Dict[str, str]:
        """Serialize record values to CSV-safe strings."""
        return {
            field: self._serialize_value(record.get(field))
            for field in fieldnames
        }

    def _serialize_value(self, value: Any) -> str:
        """Convert a single value to CSV-safe string."""
        if value is None:
            return self.null_value

        if isinstance(value, bool):
            return 'true' if value else 'false'

        if isinstance(value, (int, float)):
            return str(value)

        if isinstance(value, Decimal):
            if self.decimal_places is not None:
                return f"{value:.{self.decimal_places}f}"
            return str(value)

        if isinstance(value, datetime):
            return value.strftime(self.datetime_format)

        if hasattr(value, 'date') and callable(value.date):  # date object
            return value.strftime(self.date_format)

        if isinstance(value, Enum):
            return str(value.value)

        if isinstance(value, (list, tuple)):
            return self._serialize_collection(value)

        if isinstance(value, dict):
            return self._serialize_dict(value)

        if is_dataclass(value):
            return self._serialize_dataclass(value)

        # Fallback to string representation
        return str(value)

    def _serialize_collection(self, value: Union[list, tuple]) -> str:
        """Serialize list/tuple as pipe-separated string."""
        items = [self._serialize_value(item) for item in value]
        return '|'.join(items)

    def _serialize_dict(self, value: dict) -> str:
        """Serialize dict as key=value pairs."""
        pairs = [f"{k}={self._serialize_value(v)}" for k, v in value.items()]
        return ';'.join(pairs)

    def _serialize_dataclass(self, value: Any) -> str:
        """Serialize nested dataclass as JSON string."""
        import json
        try:
            return json.dumps(asdict(value), default=str)
        except Exception:
            return str(value)


class JSONFormatter(BaseFormatter):
    """Formats customer data as JSON."""

    def __init__(self, indent: Optional[int] = 2, sort_keys: bool = False):
        self.indent = indent
        self.sort_keys = sort_keys

    def format(self, data: List[Any]) -> str:
        import json

        try:
            records = [
                asdict(item) if is_dataclass(item) else item
                for item in data
            ]
            return json.dumps(
                records,
                indent=self.indent,
                sort_keys=self.sort_keys,
                default=str,
            )
        except Exception as e:
            raise FormatterError(f"Failed to format data as JSON: {e}") from e

    def get_content_type(self) -> str:
        return 'application/json'

    def get_file_extension(self) -> str:
        return '.json'
```

