## 3. Export Service

```python
# src/services/export_service.py
import logging
from dataclasses import dataclass
from datetime import datetime
from enum import Enum
from typing import Dict, List, Optional, Type, TypeVar

from src.exporters.formatters.csv_formatter import (
    BaseFormatter,
    CSVFormatter,
    FormatterError,
    JSONFormatter,
)

logger = logging.getLogger(__name__)

T = TypeVar('T')


class ExportFormat(Enum):
    """Supported export formats."""
    JSON = 'json'
    CSV = 'csv'


@dataclass
class ExportConfig:
    """Configuration for data export."""
    format: ExportFormat
    include_headers: bool = True
    delimiter: str = ','
    date_format: str = '%Y-%m-%d'
    datetime_format: str = '%Y-%m-%d %H:%M:%S'


class ExportService:
    """Service for exporting customer data in multiple formats."""

    def __init__(self):
        self._formatters: Dict[ExportFormat, BaseFormatter] = {
            ExportFormat.JSON: JSONFormatter(),
            ExportFormat.CSV: CSVFormatter(),
        }

    def register_formatter(
        self,
        format_type: ExportFormat,
        formatter: BaseFormatter,
    ) -> None:
        """Register a custom formatter."""
        self._formatters[format_type] = formatter

    def export(
        self,
        data: List[T],
        config: ExportConfig,
    ) -> str:
        """
        Export data in specified format.

        Args:
            data: List of objects to export
            config: Export configuration

        Returns:
            Formatted data as string

        Raises:
            FormatterError: If export fails
        """
        if not data:
            logger.warning("Exporting empty dataset")
            return ''

        formatter = self._formatters.get(config.format)
        if not formatter:
            raise FormatterError(
                f"No formatter registered for format: {config.format}"
            )

        try:
            logger.info(
                f"Exporting {len(data)} records as {config.format.value}"
            )
            result = formatter.format(data)
            logger.info(f"Export successful, size: {len(result)} bytes")
            return result
        except FormatterError:
            raise
        except Exception as e:
            logger.error(f"Unexpected error during export: {e}")
            raise FormatterError(f"Export failed: {e}") from e

    def get_formatter(self, format_type: ExportFormat) -> BaseFormatter:
        """Get formatter for a specific format."""
        formatter = self._formatters.get(format_type)
        if not formatter:
            raise FormatterError(f"No formatter for format: {format_type}")
        return formatter
