    """Context passed through pipeline stages."""
    job_id: str
    format_type: str
    data: List[Any]
    formatted_data: Optional[str] = None
    delivery_method: Optional[DeliveryMethod] = None
    delivery_location: Optional[str] = None
    metadata: Dict[str, Any] = None
    started_at: datetime = None
    completed_at: Optional[datetime] = None
    error: Optional[Exception] = None

    def __post_init__(self):
        if self.metadata is None:
            self.metadata = {}
        if self.started_at is None:
            self.started_at = datetime.utcnow()


class PipelineHook(ABC):
    """Abstract base for pipeline hooks."""

    @abstractmethod
    def execute(self, context: PipelineContext) -> None:
        """Execute hook logic."""
        pass

    @abstractmethod
    def get_stage(self) -> PipelineStage:
        """Return the stage this hook executes in."""
        pass

    @abstractmethod
    def get_name(self) -> str:
        """Return hook name for logging."""
        pass


class ValidationHook(PipelineHook):
    """Hook for data validation."""

    def __init__(self, validators: Optional[List[Callable]] = None):
        self.validators = validators or []

    def execute(self, context: PipelineContext) -> None:
        logger.info(f"[{context.job_id}] Running validation hooks")

        if not context.data:
            raise ValueError("No data to export")

        for validator in self.validators:
            validator(context.data)

        logger.info(f"[{context.job_id}] Validation passed")

    def get_stage(self) -> PipelineStage:
        return PipelineStage.VALIDATION

    def get_name(self) -> str:
        return 'validation'


class TransformationHook(PipelineHook):
    """Hook for data transformation."""

    def __init__(self, transformers: Optional[List[Callable]] = None):
        self.transformers = transformers or []

    def execute(self, context: PipelineContext) -> None:
        logger.info(f"[{context.job_id}] Running transformation hooks")

        for transformer in self.transformers:
            context.data = transformer(context.data)

        logger.info(
            f"[{context.job_id}] Transformation complete, "
            f"{len(context.data)} records"
        )

    def get_stage(self) -> PipelineStage:
        return PipelineStage.TRANSFORMATION

    def get_name(self) -> str:
        return 'transformation'


class FormattingHook(PipelineHook):
    """Hook for data formatting."""

    def __init__(self, formatter: Callable):
        self.formatter = formatter

    def execute(self, context: PipelineContext) -> None:
        logger.info(
            f"[{context.job_id}] Formatting data as {context.format_type}"
        )

        context.formatted_data = self.formatter(context.data)

        logger.info(
            f"[{context.job_id}] Formatting complete, "
            f"size: {len(context.formatted_data)} bytes"
        )

    def get_stage(self) -> PipelineStage:
        return PipelineStage.FORMATTING

    def get_name(self) -> str:
        return 'formatting'


class DeliveryHook(PipelineHook):
    """Hook for data delivery."""

    def __init__(self, deliverer: Callable):
        self.deliverer = deliverer

    def execute(self, context: PipelineContext) -> None:
        logger.info(
            f"[{context.job_id}] Delivering via {context.delivery_method}"
        )

        self.deliverer(context)

        logger.info(
            f"[{context.job_id}] Delivery complete to "
            f"{context.delivery_location}"
        )

    def get_stage(self) -> PipelineStage:
        return PipelineStage.DELIVERY

    def get_name(self) -> str:
        return 'delivery'


class CleanupHook(PipelineHook):
    """Hook for cleanup operations."""

    def __init__(self, cleanup_funcs: Optional[List[Callable]] = None):
        self.cleanup_funcs = cleanup_funcs or []

    def execute(self, context: PipelineContext) -> None:
        logger.info(f"[{context.job_id}] Running cleanup hooks")

        for cleanup_func in self.cleanup_funcs:
            try:
                cleanup_func(context)
            except Exception as e:
                logger.warning(
                    f"[{context.job_id}] Cleanup function failed: {e}"
                )

    def get_stage(self) -> PipelineStage:
        return PipelineStage.CLEANUP

    def get_name(self) -> str:
        return 'cleanup'


class DeliveryPipeline:
    """Main delivery pipeline orchestrator."""

    def __init__(self):
        self.hooks: Dict[PipelineStage, List[PipelineHook]] = {
            stage: [] for stage in PipelineStage
        }

    def register_hook(self, hook: PipelineHook) -> None:
        """Register a hook for a specific stage."""
        stage = hook.get_stage()
        self.hooks[stage].append(hook)
        logger.debug(f"Registered hook '{hook.get_name()}' for stage {stage}")

    def execute(self, context: PipelineContext) -> PipelineContext:
        """
        Execute pipeline with all registered hooks.

        Args:
            context: Pipeline context

        Returns:
            Updated context

        Raises:
            Exception: If any hook fails
        """
        logger.info(f"[{context.job_id}] Starting pipeline execution")

        try:
            # Execute hooks in stage order
            for stage in PipelineStage:
                logger.info(f"[{context.job_id}] Executing stage: {stage}")

                for hook in self.hooks[stage]:
                    try:
                        logger.debug(
                            f"[{context.job_id}] Running hook: "
                            f"{hook.get_name()}"
                        )
                        hook.execute(context)
                    except Exception as e:
                        logger.error(
                            f"[{context.job_id}] Hook '{hook.get_name()}' "
                            f"failed: {e}",
                            exc_info=True,
                        )
                        context.error = e
                        raise

            context.completed_at = datetime.utcnow()
            logger.info(
                f"[{context.job_id}] Pipeline completed successfully in "
                f"{(context.completed_at - context.started_at).total_seconds():.2f}s"
            )
            return context

        except Exception as e:
            context.completed_at = datetime.utcnow()
            logger.error(
                f"[{context.job_id}] Pipeline failed after "
                f"{(context.completed_at - context.started_at).total_seconds():.2f}s: {e}"
            )
            raise
