# src/pipeline/deliverers.py
import logging
import os
from abc import ABC, abstractmethod
from pathlib import Path
from typing import Optional

logger = logging.getLogger(__name__)


class Deliverer(ABC):
    """Abstract base for delivery implementations."""

    @abstractmethod
    def deliver(self, context) -> None:
        """Deliver formatted data."""
        pass


class LocalFileDeliverer(Deliverer):
    """Delivers data to local filesystem."""

    def __init__(self, base_path: str = '/tmp/exports'):
        self.base_path = Path(base_path)
        self.base_path.mkdir(parents=True, exist_ok=True)

    def deliver(self, context) -> None:
        """Write data to local file."""
        from src.exporters.formatters.csv_formatter import CSVFormatter

        formatter = CSVFormatter() if context.format_type == 'csv' else None
        extension = formatter.get_file_extension() if formatter else '.json'

        filename = f"{context.job_id}_{context.format_type}{extension}"
        filepath = self.base_path / filename

        with open(filepath, 'w') as f:
            f.write(context.formatted_data)

        context.delivery_location = str(filepath)
        logger.info(f"Delivered to local file: {filepath}")


class S3Deliverer(Deliverer):
    """Delivers data to AWS S3."""

    def __init__(self, bucket: str, prefix: str = 'exports'):
        self.bucket = bucket
        self.prefix = prefix
        try:
            import boto3
            self.s3_client = boto3.client('s3')
        except ImportError:
            raise ImportError("boto3 required for S3 delivery")

    def deliver(self, context) -> None:
        """Upload data to S3."""
        from src.exporters.formatters.csv_formatter import CSVFormatter

        formatter = CSVFormatter() if context.format_type == 'csv' else None
        extension = formatter.get_file_extension() if formatter else '.json'

        key = f"{self.prefix}/{context.job_id}_{context.format_type}{extension}"

        self.s3_client.put_object(
            Bucket=self.bucket,
            Key=key,
            Body=context.formatted_data.encode('utf-8'),
            ContentType='text/csv' if context.format_type == 'csv' else 'application/json',
        )

        context.delivery_location = f"s3://{self.bucket}/{key}"
        logger.info(f"Delivered to S3: {context.delivery_location}")


class EmailDeliverer(Deliverer):
    """Delivers data via email."""

    def __init__(
        self,
        smtp_host: str,
        smtp_port: int = 587,
        sender_email: str = None,
        sender_password: str = None,
    ):
        self.smtp_host = smtp_host
        self.smtp_port = smtp_port
        self.sender_email = sender_email or os.getenv('EXPORT_EMAIL_FROM')
        self.sender_password = sender_password or os.getenv('EXPORT_EMAIL_PASSWORD')

    def deliver(self, context) -> None:
        """Send data via email."""
        import smtplib
        from email.mime.base import MIMEBase
        from email.mime.multipart import MIMEMultipart
        from email.mime.text import MIMEText
        from email import encoders

        recipient = context.metadata.get('recipient_email')
        if not recipient:
            raise ValueError("recipient_email required in context metadata")

        from src.exporters.formatters.csv_formatter import CSVFormatter

        formatter = CSVFormatter() if context.format_type == 'csv' else None
        extension = formatter.get_file_extension() if formatter else '.json'
        filename = f"export_{context.job_id}{extension}"

        msg = MIMEMultipart()
        msg['From'] = self.sender_email
        msg['To'] = recipient
        msg['Subject'] = f"Customer Data Export - {context.job_id}"

        body = f"Please find attached the customer data export in {context.format_type.upper()} format."
        msg.attach(MIMEText(body, 'plain'))

        # Attach file
        attachment = MIMEBase('application', 'octet-stream')
        attachment.set_payload(context.formatted_data.encode('utf-8'))
        encoders.encode_base64(attachment)
        attachment.add_header('Content-Disposition', f'attachment; filename= {filename}')
        msg.attach(attachment)

        with smtplib.SMTP(self.smtp_host, self.smtp_port) as server:
            server.starttls()
            server.login(self.sender_email, self.sender_password)
            server.send_message(msg)

        context.delivery_location = recipient
        logger.info(f"Delivered via email to: {recipient}")
