class PipelineFactory:
    """Factory for creating configured pipelines."""

    @staticmethod
    def create_reporting_pipeline(
        export_service: ExportService,
        delivery_method: DeliveryMethod = DeliveryMethod.LOCAL,
        s3_bucket: Optional[str] = None,
    ) -> DeliveryPipeline:
        """
        Create the reporting team's delivery pipeline.

        Includes:
        - Data validation
        - Filtering transformations
        - CSV/JSON formatting
        - Multi-method delivery
        - Cleanup
        """
        pipeline = DeliveryPipeline()

        # Validation stage
        validation_hook = ValidationHook(
            validators=[
                PipelineFactory._validate_customer_data,
            ]
        )
        pipeline.register_hook(validation_hook)

        # Transformation stage
        transformation_hook = TransformationHook(
            transformers=[
                PipelineFactory._filter_active_customers,
                PipelineFactory._enrich_customer_data,
            ]
        )
        pipeline.register_hook(transformation_hook)

        # Formatting stage
        def format_data(data):
            # This will be set per-request based on format_type
            return data

        formatting_hook = FormattingHook(
            formatter=lambda data: PipelineFactory._format_data(
                data, export_service
            )
        )
        pipeline.register_hook(formatting_hook)

        # Delivery stage
        if delivery_method == DeliveryMethod.S3:
            if not s3_bucket:
                raise ValueError("s3_bucket required for S3 delivery")
            deliverer = S3Deliverer(bucket=s3_bucket)
        else:
            deliverer = LocalFileDeliverer()

        delivery_hook = DeliveryHook(
            deliverer=lambda ctx: deliverer.deliver(ctx)
        )
        pipeline.register_hook(delivery_hook)

        # Cleanup stage
        cleanup_hook = CleanupHook(
            cleanup_funcs=[
                PipelineFactory._log_export_metrics,
            ]
        )
        pipeline.register_hook(cleanup_hook)

        return pipeline

    @staticmethod
    def _validate_customer_data(data: List) -> None:
        """Validate customer data structure."""
        if not data:
