// db/router.ts
import { Database } from 'bun:sqlite';
import { EventEmitter } from 'node:events';

type QueryType = 'read' | 'write';

interface RouteDecision {
  target: 'local' | 'remote';
  reason: string;
}

interface Stats {
  localReads: number;
  localWrites: number;
  remoteReads: number;
  remoteWrites: number;
  lastDecision: RouteDecision | null;
}

export class LocalFirstRouter {
  private local: Database;
  private stats: Stats = {
    localReads: 0,
    localWrites: 0,
    remoteReads: 0,
    remoteWrites: 0,
    lastDecision: null,
  };

  private emitter = new EventEmitter();

  // Configurable thresholds – these must be tuned from real measurements
  constructor(
    localDbPath: string = ':memory:',
    private config: {
      maxLocalWriteQps?: number;        // e.g. 200
      maxLocalConcurrentWrites?: number; // e.g. 8
      preferLocalReads?: boolean;       // default true for local-first
    } = {}
  ) {
    this.local = new Database(localDbPath);
    this.local.exec('PRAGMA journal_mode = WAL;');
    this.local.exec('PRAGMA synchronous = NORMAL;');
  }

  private classify(sql: string): QueryType {
    const trimmed = sql.trim().toUpperCase();
    return trimmed.startsWith('SELECT') || trimmed.startsWith('PRAGMA')
      ? 'read'
      : 'write';
  }

  private decide(sql: string, estimatedCost = 1): RouteDecision {
    const type = this.classify(sql);

    if (type === 'write') {
      // For now everything writes locally (local-first principle).
      // Remote write routing would require observed replication strategy.
      this.stats.localWrites += estimatedCost;
      const decision: RouteDecision = { target: 'local', reason: 'local-first write' };
      this.stats.lastDecision = decision;
      return decision;
    }

    // Read routing
    if (this.config.preferLocalReads !== false) {
      this.stats.localReads += estimatedCost;
      const decision: RouteDecision = { target: 'local', reason: 'local-first read' };
      this.stats.lastDecision = decision;
      return decision;
    }

    // Placeholder for future remote read path once we observe Aurora setup
    this.stats.remoteReads += estimatedCost;
    const decision: RouteDecision = { target: 'remote', reason: 'remote-read policy' };
    this.stats.lastDecision = decision;
    return decision;
  }

  exec(sql: string, params?: any[]): any {
    const decision = this.decide(sql);
    this.emit('query', { sql, params, decision, stats: { ...this.stats } });

    if (decision.target === 'local') {
      return this.local.query(sql).all(...(params ?? []));
    }

    throw new Error('Remote execution path not yet implemented – provide observed remote client');
  }

  run(sql: string, params?: any[]): { lastInsertRowid: number; changes: number } {
    const decision = this.decide(sql);
    this.emit('query', { sql, params, decision, stats: { ...this.stats } });

    if (decision.target === 'local') {
      return this.local.run(sql, ...(params ?? []));
    }

    throw new Error('Remote execution path not yet implemented');
  }

  on(event: 'query', listener: (info: any) => void) {
    this.emitter.on(event, listener);
  }

  getStats(): Readonly<Stats> {
    return { ...this.stats };
  }

  private emit(event: string, data: any) {
    this.emitter.emit(event, data);
  }

  // For testing / observability
  resetStats() {
    this.stats = { localReads: 0, localWrites: 0, remoteReads: 0, remoteWrites: 0, lastDecision: null };
  }
}
