```go
// internal/export/formatter/csv.go
package formatter

import (
	"bytes"
	"encoding/csv"
	"fmt"
	"io"
	"time"

	"yourcompany.com/customer-export/internal/model"
)

// CSVFormatter implements Formatter for CSV output
type CSVFormatter struct{}

func NewCSVFormatter() *CSVFormatter {
	return &CSVFormatter{}
}

func (f *CSVFormatter) Format(customers []*model.Customer) (io.Reader, string, error) {
	if len(customers) == 0 {
		return bytes.NewReader([]byte{}), "text/csv", nil
	}

	var buf bytes.Buffer
	writer := csv.NewWriter(&buf)

	// Write header
	header := []string{
		"id", "email", "first_name", "last_name", "phone",
		"status", "created_at", "updated_at", "tags", "metadata",
	}
	if err := writer.Write(header); err != nil {
		return nil, "", fmt.Errorf("failed to write CSV header: %w", err)
	}

	for _, c := range customers {
		record := []string{
			c.ID,
			c.Email,
			c.FirstName,
			c.LastName,
			c.Phone,
			string(c.Status),
			c.CreatedAt.Format(time.RFC3339),
			c.UpdatedAt.Format(time.RFC3339),
			formatTags(c.Tags),
			formatMetadata(c.Metadata),
		}
		if err := writer.Write(record); err != nil {
			return nil, "", fmt.Errorf("failed to write customer row: %w", err)
		}
	}

	writer.Flush()
	if err := writer.Error(); err != nil {
		return nil, "", fmt.Errorf("csv writer error: %w", err)
	}

	return &buf, "text/csv", nil
}

func formatTags(tags []string) string {
	if len(tags) == 0 {
		return ""
	}
	// Simple comma-separated for CSV (could be JSON if you prefer)
	return fmt.Sprintf(`"%s"`, joinWithEscape(tags, ","))
}

func formatMetadata(m map[string]any) string {
	if len(m) == 0 {
		return ""
	}
	// For CSV we stringify as JSON to preserve structure
	b, _ := json.Marshal(m) // safe to ignore error in this context
	return string(b)
}

func joinWithEscape(items []string, sep string) string {
	// Very basic escaping for CSV
	for i, s := range items {
		if containsCommaOrQuote(s) {
			items[i] = `"` + escapeQuotes(s) + `"`
		}
	}
	return strings.Join(items, sep)
}

func containsCommaOrQuote(s string) bool {
	return strings.ContainsAny(s, `,"`)
}

func escapeQuotes(s string) string {
	return strings.ReplaceAll(s, `"`, `""`)
}
```

