	customers, err := s.repo.GetCustomers(ctx, req.Filters)
	if err != nil {
		return "", fmt.Errorf("failed to fetch customers: %w", err)
	}

	f, err := formatter.Get(req.Format)
	if err != nil {
		return "", err
	}

	reader, contentType, err := f.Format(customers)
	if err != nil {
		return "", fmt.Errorf("formatting failed: %w", err)
	}

	exportID := uuid.NewString()
	filename := fmt.Sprintf("customers-%s.%s", exportID, req.Format)

	event := &events.CustomerDataExported{
		ExportID:    exportID,
		Filename:    filename,
		ContentType: contentType,
		Format:      string(req.Format),
		RecordCount: len(customers),
		Requester:   req.Requester,
		Data:        reader,
		Timestamp:   time.Now(),
	}

	if err := s.publisher.Publish(ctx, event); err != nil {
		return "", fmt.Errorf("failed to publish export event: %w", err)
	}

	return exportID, nil
}
