```ts
// healthcheck.ts
import { parseArgs } from "util";

const { values, positionals } = parseArgs({
  args: process.argv.slice(2),
  options: {
    config: { type: "string", short: "c" },
    url: { type: "string", short: "u" },
    timeout: { type: "string", default: "10000" },
    json: { type: "boolean", short: "j" },
  },
  allowPositionals: true,
});

async function main() {
  let urls: string[] = [];

  if (values.url) {
    urls = [values.url];
  } else if (values.config) {
    const config = await Bun.file(values.config).json();
    urls = config.urls || config.targets || [];
  } else if (positionals.length > 0) {
    urls = positionals;
  } else {
    console.error("Provide --url, --config, or positional URLs");
    process.exit(1);
  }

  const timeout = parseInt(values.timeout as string, 10);
  const results = [];

  for (const url of urls) {
    const start = Date.now();
    try {
      const controller = new AbortController();
      const id = setTimeout(() => controller.abort(), timeout);

      const res = await fetch(url, { signal: controller.signal });
      clearTimeout(id);

      const success = res.ok && res.status === 200;
      const result = {
        url,
        status: res.status,
        ok: success,
        latency: Date.now() - start,
        timestamp: new Date().toISOString(),
      };

      results.push(result);

      if (!values.json) {
        console.log(
          `${success ? "✅" : "❌"} ${res.status} ${url} (${result.latency}ms)`
        );
      }
    } catch (err: any) {
      const result = {
        url,
        ok: false,
        error: err.name === "AbortError" ? "timeout" : err.message,
        latency: Date.now() - start,
        timestamp: new Date().toISOString(),
      };
      results.push(result);

      if (!values.json) {
        console.log(`❌ ${url} (${result.error})`);
      }
    }
  }

  if (values.json) {
    console.log(JSON.stringify(results, null, 2));
  }

  const allGood = results.every(r => r.ok);
  process.exit(allGood ? 0 : 1);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});
```

