// Minimal load-aware query router with circuit breakers
import { Database } from 'bun:sqlite';
import { Client } from '@libsql/client';

const LOCAL_LOAD_LIMIT = process.env.LOCAL_CONCURRENT_LIMIT || 5;
const REMOTE_TIMEOUT = process.env.REMOTE_TIMEOUT_MS || 2000;

class EmpiricalRouter {
  private local: Database;
  private remote: Client;
  private activeQueries = 0;
  private circuitOpen = false;

  constructor() {
    this.local = new Database('local.db');
    this.remote = new Client({
      url: process.env.AURORA_URL,
      authToken: process.env.AURORA_TOKEN
    });
  }

  async query<T>(sql: string): Promise<T> {
    if (this.circuitOpen || this.activeQueries >= LOCAL_LOAD_LIMIT) {
      return this.failoverQuery<T>(sql);
    }

    this.activeQueries++;

    try {
      const result = await this.local.query(sql).get();
      this.activeQueries--;
      return result as T;
    } catch (error) {
      this.activeQueries--;
      return this.failoverQuery<T>(sql);
    }
  }

  private async failoverQuery<T>(sql: string): Promise<T> {
    const timeout = new Promise((_, reject) => 
      setTimeout(() => reject('Remote timeout'), REMOTE_TIMEOUT));

    try {
      const result = await Promise.race([
        this.remote.execute(sql),
        timeout
      ]);
      return result as T;
    } catch (error) {
      this.circuitOpen = true;
      setTimeout(() => this.circuitOpen = false, 10000);
      throw new Error(`Fallback failed: ${error}`);
    }
  }
}
