extractErrorLines('./app.log', './errors.log')
  .then(result => console.log(`Extracted errors to ${result.written}`));

// Or collect in memory (if error count is manageable)
extractErrorLines('./app.log')
  .then(errors => console.log(`Found ${errors.length} error lines`));
```

