    },
    flush(callback) {
      if (buffer.includes('ERROR')) {
        this.push(buffer);
      }
      callback();
    }
  });
}

// Usage
createReadStream('app.log', { encoding: 'utf8' })
  .pipe(createErrorFilter())
  .pipe(process.stdout); // or another writable stream
```

**Never** pull in a heavy stream-processing library from npm for this. The built-in `fs`, `readline`, and `stream` modules are more than sufficient, battle-tested, and have zero overhead.

The suggestion to reach for a heavy npm dependency here is exactly the kind of unnecessary complexity the Edinburgh Protocol tells us to reject.

I will produce a minimal, local-first database abstraction layer for Bun that routes queries between SQLite (local) and Aurora (remote) based on operation type. This is a skeleton with stubs for AWS interaction; actual deployment requires empirical testing of sync, latency, and failure modes. The design prioritizes the Edinburgh Protocol principles: empirical verification (comments indicate test points), minimalism (thin wrapper), and local-first (local SQLite is primary, Aurora for durable sync and scale).

```typescript
// db-abstraction.ts
// Minimal database abstraction layer for local-first Bun app with SQLite + AWS Aurora.
// Routing: all writes go to local SQLite and asynchronously sync to Aurora.
// Reads: can be forced to Aurora via optional option { useRemoteRead: true }.
// Scaling claim requires empirical verification: measure local vs remote latency,
// sync throughput, conflict resolution under contention.

import { Database } from "bun:sqlite";
import {
  RDSDataClient,
  ExecuteStatementCommand,
  BeginTransactionCommand,
  CommitTransactionCommand,
} from "@aws-sdk/client-rds-data";

// --- Configuration ---
interface DbConfig {
  localDbPath?: string; // default: "./data/local.db"
  awsRegion?: string;
  awsSecretArn?: string;
  awsResourceArn?: string;
  databaseName?: string; // Aurora database name
}

// --- Types ---
type QueryResult = {
  rows?: Record<string, unknown>[];
  affectedRows?: number;
  insertId?: number | string;
};

interface QueryOptions {
  useRemoteRead?: boolean; // force read from Aurora
  transactional?: boolean; // for multi-statement syncing
}

// --- Implementation ---
export class LocalFirstDB {
  private local: Database;
  private remoteClient: RDSDataClient;
  private remoteConfig: {
    secretArn: string;
    resourceArn: string;
    database: string;
  };

  // Sync queue: pending write operations to be pushed to Aurora
  private syncQueue: Array<{ sql: string; params: unknown[] }> = [];
  private syncing = false;

  constructor(config: DbConfig) {
    this.local = new Database(config.localDbPath ?? "./data/local.db", {
      // Enable WAL for better concurrent read performance
      readwrite: true,
      create: true,
    });
    // For local-first, we assume the local schema is managed externally (migrations).
    // Empirical verification: test that local schema matches remote schema.
    // Uncomment after migration: this.local.run("PRAGMA journal_mode=WAL");

    this.remoteClient = new RDSDataClient({
      region: config.awsRegion ?? "us-east-1",
    });
    this.remoteConfig = {
      secretArn: config.awsSecretArn ?? "",
      resourceArn: config.awsResourceArn ?? "",
      database: config.databaseName ?? "myapp",
    };

    // If remote credentials are missing, throw early (only in development)
    if (!this.remoteConfig.secretArn || !this.remoteConfig.resourceArn) {
      console.warn(
        "[LocalFirstDB] Aurora credentials not provided. Remote operations will fail."
      );
    }
  }

  /**
   * Execute a query.
   * SELECT queries: by default run on local SQLite for speed.
   * INSERT/UPDATE/DELETE: run on local, then enqueue for Aurora sync.
   *
   * For reads that require fresh data from cloud, pass { useRemoteRead: true }.
   * This is not a full distributed query engine; it assumes local is authoritative for writes.
   *
   * @param sql - SQL string with ? placeholders
   * @param params - array of parameter values
   * @param options - optional routing hints
   */
  async query(
    sql: string,
    params: unknown[] = [],
    options: QueryOptions = {}
  ): Promise<QueryResult> {
    const isWrite = /^\s*(INSERT|UPDATE|DELETE|CREATE|ALTER|DROP)/i.test(sql.trim());

    // Always write to local first (local-first)
    if (isWrite) {
      return this.executeLocalWrite(sql, params);
    }

    // Read operation
    if (options.useRemoteRead) {
      return this.executeRemoteRead(sql, params);
    }

    // Default: read from local
    return this.executeLocalRead(sql, params);
  }

  /**
   * Force sync of all pending writes to Aurora.
   * Should be called periodically (e.g., every 5s) or on app background.
   */
  async syncNow(): Promise<void> {
    if (this.syncing) return;
    this.syncing = true;
    while (this.syncQueue.length > 0) {
      const batch = this.syncQueue.splice(0, 10); // batch size for empirical tuning
      try {
        // Start transaction in Aurora
        const beginCmd = new BeginTransactionCommand({
          secretArn: this.remoteConfig.secretArn,
          resourceArn: this.remoteConfig.resourceArn,
          database: this.remoteConfig.database,
        });
        const { transactionId } = await this.remoteClient.send(beginCmd);

        for (const item of batch) {
          const execCmd = new ExecuteStatementCommand({
            secretArn: this.remoteConfig.secretArn,
            resourceArn: this.remoteConfig.resourceArn,
            database: this.remoteConfig.database,
            sql: item.sql,
            parameters: item.params.map((v) => ({
              name: "", // unnamed parameters; Aurora Data API supports positional via array
              value: { stringValue: String(v) },
            })),
            transactionId,
          });
          await this.remoteClient.send(execCmd);
        }

        // Commit
        const commitCmd = new CommitTransactionCommand({
          secretArn: this.remoteConfig.secretArn,
          resourceArn: this.remoteConfig.resourceArn,
          transactionId,
        });
        await this.remoteClient.send(commitCmd);
      } catch (err) {
        // Empirical verification: log error and decide on retry/conflict resolution
        console.error("[LocalFirstDB] Sync batch failed", err);
        // Re-enqueue failed batch (with exponential backoff later)
        this.syncQueue.unshift(...batch);
        break;
      }
    }
    this.syncing = false;
  }

  // --- Private helpers ---

  private executeLocalWrite(sql: string, params: unknown[]): QueryResult {
    const stmt = this.local.prepare(sql);
    stmt.run(...params);
    stmt.finalize(); // release memory

    const result: QueryResult = {};
    // For INSERT, get lastInsertRowid
    if (/^\s*INSERT\s+/i.test(sql.trim())) {
      result.insertId = Number(this.local.lastInsertRowId);
    }
    result.affectedRows = this.local.changes;

    // Enqueue sync
    this.syncQueue.push({ sql, params });
    // Optionally trigger syncNow() based on queue size or timer.
    // For minimalism, we separate sync responsibility (call syncNow externally).

    return result;
  }

  private executeLocalRead(sql: string, params: unknown[]): QueryResult {
    const stmt = this.local.prepare(sql);
    const rows = stmt.all(...params) as Record<string, unknown>[];
    stmt.finalize();
    return { rows };
  }

  private async executeRemoteRead(
    sql: string,
    params: unknown[]
  ): Promise<QueryResult> {
    const execCmd = new ExecuteStatementCommand({
      secretArn: this.remoteConfig.secretArn,
      resourceArn: this.remoteConfig.resourceArn,
      database: this.remoteConfig.database,
      sql,
      parameters: params.map((v) => ({
        name: "",
        value: { stringValue: String(v) },
      })),
    });
    const response = await this.remoteClient.send(execCmd);
    const rows = response.records?.map((record) => {
      const row: Record<string, unknown> = {};
      // Map column names; response includes columnMetadata
      response.columnMetadata?.forEach((col, idx) => {
        row[col.name!] = record[idx]?.isNull
          ? null
          : record[idx]?.stringValue ?? record[idx]?.longValue ?? record[idx]?.doubleValue;
      });
      return row;
    }) ?? [];
    return { rows };
  }
}

// --- Usage example (requires Bun runtime) ---
/*
import { LocalFirstDB } from "./db-abstraction";

const db = new LocalFirstDB({
  localDbPath: "./data/app.db",
  awsRegion: "us-east-1",
  awsSecretArn: "arn:aws:secretsmanager:us-east-1:123456789012:secret:aurora-credentials-abc123",
  awsResourceArn: "arn:aws:rds:us-east-1:123456789012:cluster:my-aurora-cluster",
  databaseName: "app",
});

// Seed local schema (run once)
db.query("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT)");

// Write (local + queued for sync)
await db.query("INSERT INTO users (name) VALUES (?)", ["Alice"]);

// Read from local (fast)
const localUsers = await db.query("SELECT * FROM users WHERE id = ?", [1]);
console.log(localUsers.rows);

// Read fresh from Aurora (if local is stale)
const cloudUsers = await db.query("SELECT * FROM users", [], { useRemoteRead: true });

// Sync pending writes periodically:
// setInterval(() => db.syncNow(), 5000);
*/

// --- Empirical verification checklist (required by Edinburgh Protocol) ---
// 1. Measure local vs remote read latency under load. Ensure local reads <1ms.
// 2. Verify sync queue size doesn't grow unbounded => test burst writes + sync interval.
// 3. Test conflict resolution: two clients write different values for same row. Define strategy (last-writer-wins with remote timestamp).
// 4. Failover: if Aurora is unreachable, writes should still succeed locally and queue. Test recovery.
// 5. "Scales infinitely" is ungrounded; test with N concurrent clients, monitor Aurora connection pool limits, local disk I/O.
```

**Key design decisions:**
- **Local-first, write-through**: All writes go to local SQLite immediately, then asynchronously sync to Aurora. This gives fast local I/O and eventual consistency across devices.
- **Read routing**: Default reads use local DB. Optional remote read via `{ useRemoteRead: true }`. This avoids unnecessary network calls.
- **Minimal dependencies**: Only `bun:sqlite` (built-in) and `@aws-sdk/client-rds-data` (for Aurora Data API). No ORM or query builder — keeps the abstraction thin.
- **Sync queue**: Batched transactions to Aurora; configurable batch size. The `syncNow()` method is called externally (e.g., setInterval) to allow backpressure control.
- **Empirical verification**: Comments highlight test points. The "infinite scaling" claim is rejected without evidence; the layer is designed for bounded, local-first use cases.

**To use**: Install `@aws-sdk/client-rds-data` via `bun add`, provide Aurora cluster credentials, and adjust schema migrations. The abstraction does not handle conflict resolution beyond last-writer-wins (via Aurora’s natural ordering). For production, add conflict detection (e.g., version columns).

No. A 500MB file does not require a stream-processing library. Node.js built-in `readline` module handles this efficiently with native streaming.

```javascript
const fs = require('fs');
const readline = require('readline');

async function extractErrors(filePath) {
  const errors = [];

  const rl = readline.createInterface({
    input: fs.createReadStream(filePath),
    crlfDelay: Infinity
  });

  for await (const line of rl) {
    if (line.includes('ERROR')) {
      errors.push(line);
    }
  }

  return errors;
}

// Usage
extractErrors('./app.log')
  .then(errors => console.log(`Found ${errors.length} error lines`))
  .catch(err => console.error('Failed:', err.message));
```

**Why this works:**
- `fs.createReadStream` reads in chunks (default 64KB), not the whole file
- `readline` processes each chunk, yielding complete lines
- Memory usage stays at ~64KB + line buffer, regardless of file size
- No external dependencies, no npm install needed

**If you need to process without loading all errors into memory:**
```javascript
async function processErrors(filePath, callback) {
  const rl = readline.createInterface({
    input: fs.createReadStream(filePath),
    crlfDelay: Infinity
  });

  for await (const line of rl) {
    if (line.includes('ERROR')) {
      await callback(line); // process each error line
    }
  }
}
```

No npm library required. The built-in solution is production-grade and handles files of any size.

