**`unified-db.ts`**
```ts
/**
 * Local-first database abstraction for Bun.
 * - Writes always hit local SQLite first (empirical local-first guarantee).
 * - Reads can be served from SQLite or forwarded to AWS Aurora based on `strategy`.
 * - Routing is a deterministic, observable heuristic — not a black‑box "infinite scale" switch.
 * - True infinite scaling requires sharding, caching (e.g. Redis), and data‑consistency patterns;
 *   this layer provides the minimal foundation for local-first workflows.
 *
 * Usage:
 *   import { UnifiedDB } from './unified-db.ts'
 *   const db = new UnifiedDB({
 *     sqlitePath: './local.db',
 *     aurora: { host, port, database, user, password }, // optional, omit for local‑only
 *     strategy: 'local-first' | 'remote-first' | 'load-balanced'
 *   })
 *   const users = await db.query('SELECT * FROM users WHERE id = ?', [uid])
 */

import { Database as SqliteDatabase } from 'bun:sqlite'

type RoutingStrategy = 'local-first' | 'remote-first' | 'load-balanced'

interface AuroraConfig {
  host: string
  port: number
  database: string
  user: string
  password: string
}

/**
 * Unified abstraction over Bun SQLite + optional AWS Aurora.
 * All writes go to SQLite. Reads respect the configured strategy.
 */
export class UnifiedDB {
  private sqlite: SqliteDatabase
  private auroraPool: import('mysql2/promise').Pool | null
  private strategy: RoutingStrategy
  private readCounter = 0

  constructor({
    sqlitePath,
    aurora,
    strategy = 'local-first',
  }: {
    sqlitePath: string
    aurora?: AuroraConfig
    strategy?: RoutingStrategy
  }) {
    this.sqlite = new SqliteDatabase(sqlitePath)
    this.strategy = strategy ?? 'local-first'
    this.auroraPool = aurora
      ? new (await import('mysql2/promise')).createPool({
          host: aurora.host,
          port: aurora.port,
          database: aurora.database,
          user: aurora.user,
          password: aurora.password,
          waitForConnections: true,
          connectionLimit: 10,
        })
      : null
  }

  /** Determine target based on SQL type + strategy */
  private routeTarget(sql: string): 'sqlite' | 'aurora' {
    const first = sql.trim().split(/\s+/)[0].toUpperCase()
    if (/^(INSERT|UPDATE|DELETE|REPLACE)$/.test(first)) return 'sqlite'

    if (this.strategy === 'local-first') return 'sqlite'
    if (this.strategy === 'remote-first') return this.auroraPool ? 'aurora' : 'sqlite'

    // load-balanced: simple deterministic round‑robin on reads
    if (this.strategy === 'load-balanced') {
      this.readCounter++
      return this.readCounter % 2 === 0 ? 'aurora' : 'sqlite'
    }
    return 'sqlite'
  }

  /** Execute a SQL statement and return rows (for SELECT) or results (for writes). */
  async query(sql: string, params?: readonly unknown[]) {
    const target = this.routeTarget(sql)

    if (target === 'sqlite') {
      if (/^\s*SELECT/i.test(sql)) {
        return this.sqlite.query(sql, params)
      }
      return this.sqlite.run(sql, params)
    }

    if (target === 'aurora' && this.auroraPool) {
      const [rows] = await this.auroraPool.execute(sql, params ?? [])
      return rows
    }

    // fallback to local
    if (/^\s*SELECT/i.test(sql)) {
      return this.sqlite.query(sql, params)
    }
    return this.sqlite.run(sql, params)
  }

  /** Convenience: SELECT */
  async select<T>(sql: string, params?: readonly unknown[]): Promise<T[]> {
    return this.query(sql, params)
  }

  /** Convenience: INSERT / UPDATE / DELETE */
  async exec(sql: string, params?: readonly unknown[]) {
    return this.query(sql, params)
  }

  /** Transaction guard – writes always stay on the local SQLite connection. */
  transaction<T>(fn: (db: UnifiedDB) => Promise<T>): Promise<T> {
    return this.sqlite.transaction(async () => fn(this))
  }

  /** Graceful cleanup */
  async end(): Promise<void> {
    if (this.auroraPool) {
      await this.auroraPool.end()
    }
  }
}
```

**Empirical grounding & scaling note**
- Writes are *always* directed to the local Bun SQLite instance. This is the local-first contract: no remote write without explicit opt‑in, and it gives you immediate, consistent latency.
- Reads are routed by a pure function of the SQL prefix and the configured `strategy`. There is no hidden state, no auto‑detected "load" that magically scales — the `load-balanced` mode uses a deterministic counter you can replace with real metrics if desired.
- The Aurora pool is lazily created and fully interchangeable with any `mysql2/promise`‑compatible endpoint. If Aurora is omitted, the layer becomes 100% local‑SQLite with zero external dependencies.
- "Infinite scaling" is not claimed. This layer gives you a measurable, auditable routing point. To actually scale beyond a single node, you'll need connection pooling, read‑through caching, sharding logic, and conflict‑resolution strategies — all of which can be composed *on top* of this abstraction without modifying its core.

