    encoding: 'utf8',
    // Standard 64KB highWaterMark is optimal for sequential local reads
  });

  const rl = createInterface({
    input: fileStream,
    crlfDelay: Infinity, // Recognizes all CR/LF variations as single newlines
  });

  for await (const line of rl) {
