### Usage

```javascript
import { extractErrorLogs } from './logParser.js';

async function run() {
  const logPath = './app-large.log';

  try {
    for await (const errorLine of extractErrorLogs(logPath)) {
      // Process error line as it streams in
      console.log(errorLine);
    }
  } catch (err) {
    console.error('Failed to process log file:', err);
  }
}

run();
